#[derive(Debug, Clone, PartialEq)]
struct Complex {
    re: i32,
    im: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // If array is empty, return it unchanged (or empty - same thing)
    if arr.is_empty() {
        return arr;
    }
    
    // Calculate threshold = tol * 2, handling potential overflow
    // If overflow occurs, threshold is effectively infinite (i32::MAX)
    let threshold = tol.checked_mul(2).unwrap_or(i32::MAX);
    
    // Check if all elements have |imag| ≤ threshold
    let all_close = arr.iter().all(|c| c.im.abs() <= threshold);
    
    if all_close {
        // Create new array with imaginary parts set to 0
        arr.into_iter()
            .map(|c| Complex { re: c.re, im: 0 })
            .collect()
    } else {
        // Return original array unchanged
        arr
    }
}